package FSM::Support::ISFRecordPortValues;

use strict;
use warnings;
use Carp qw(confess);
use Exporter 'import';
use Storable qw(dclone);
use FSM::Package::AggregatePathSupport;
use FSM::Composition::InterfacePortBuilder;
use FSM::Support::ISFInterfacePortMetadata qw(capture_interface_port_metadata);

our @EXPORT_OK = qw(record_value_scope record_value_reference validate_record_port_copy);

# Preparation only: callers supply resolved declaration facts, not source text.
# Local bindings mask outer declarations even when their type is unresolved.
sub record_value_scope {
    my %args = @_;
    _keys(\%args, [qw(outer local)], [], 'scope');
    my %scope;
    for my $layer (qw(outer local)) {
        my $roots = $args{$layer};
        _require(ref($roots) eq 'HASH', "$layer roots must be a map");
        for my $name (sort keys %$roots) {
            _require(_identifier($name), 'invalid declaration root');
            my $root = $roots->{$name};
            _keys($root, [qw(role type_spec)], [], "root '$name'");
            # Numeric validation can change Perl scalar flags and therefore
            # JSON kinds even without an assignment. Detach before any reads.
            $root = dclone($root);
            _require(_role($root->{role}), "root '$name' has invalid role");
            my $spec = $root->{type_spec};
            _validate_type($spec, "root '$name'") if defined $spec;
            $scope{$name} = {
                role => $root->{role},
                type_spec => FSM::Package::AggregatePathSupport->clone_structured_value($spec),
            };
        }
    }
    return \%scope;
}

# An unrelated token or unresolved binding belongs to the caller's existing
# validator. In particular, it must not fall through to a shadowed outer root.
sub record_value_reference {
    my %args = @_;
    _keys(\%args, [qw(scope token access context)], ['allow_whole'], 'reference');
    my ($scope, $token, $access, $context) = @args{qw(scope token access context)};
    _require(ref($scope) eq 'HASH', 'reference scope must be a map');
    _require(_text($context), 'reference requires context');
    _require(defined($access) && !ref($access) && ($access eq 'read' || $access eq 'write'),
        "$context has invalid access");
    my $allow_whole = $args{allow_whole} // 0;
    _require(_binary($allow_whole), "$context has invalid whole-value permission");
    return undef unless defined($token) && !ref($token)
        && $token =~ /\A([A-Za-z_]\w*)(.*)\z/s;
    my ($name, $path) = ($1, $2);
    return undef unless exists $scope->{$name};
    my $root = $scope->{$name};
    _keys($root, [qw(role type_spec)], [], "$context root '$name'");
    $root = dclone($root);
    _require(_role($root->{role}), "$context root '$name' has invalid role");
    _require($access ne 'write' || $root->{role} ne 'input',
        "$context cannot write declared input '$token'");
    return undef unless defined $root->{type_spec};
    _validate_type($root->{type_spec}, "$context root '$name'");
    my %result = (root => $name, role => $root->{role}, path_text => $path);
    if (!length $path) {
        my $spec = $root->{type_spec};
        _require($allow_whole || !_aggregate($spec),
            "$context requires a scalar value; '$token' is a whole $spec->{kind}");
        $result{type_spec} = FSM::Package::AggregatePathSupport->clone_structured_value($spec);
        $result{width} = 0 + $spec->{width};
        return \%result;
    }
    # Preserve scalar formal/local slices when they mask an outer record.
    # Core traversal accepts scalar indexing after a member; a one-member
    # wrapper supplies that anchor without changing the packed bit offsets.
    my ($path_root, $path_text) = ($root->{type_spec}, $path);
    if (!_aggregate($path_root)) {
        $path_root = _wrapper($path_root);
        $path_text = '.value' . $path;
    }
    my $resolved = FSM::Package::AggregatePathSupport->resolve_packed_range(
        root_type_spec => $path_root, path_text => $path_text,
    );
    _require($resolved->{ok}, "$context has invalid declared path '$token': "
        . ($resolved->{code} // 'unresolved'));
    _require(!_aggregate($resolved->{type_spec}),
        "$context requires a scalar leaf; '$token' resolves to $resolved->{type_spec}{kind}");
    @result{qw(type_spec width low high)} = @{$resolved}{qw(type_spec width low high)};
    return \%result;
}

# Return false for the caller's established scalar/storage-only assignment
# contract. Only a whole record port introduces the stricter copy obligation.
sub validate_record_port_copy {
    my %args = @_;
    _keys(\%args, [qw(source target context)], [], 'copy');
    my ($source, $target, $context) = @args{qw(source target context)};
    _require(_text($context), 'copy requires context');
    $source = dclone($source) if ref($source) eq 'HASH';
    $target = dclone($target) if ref($target) eq 'HASH';
    _validate_reference($_, $context) for grep { defined $_ } ($source, $target);
    return 0 unless _record_port($source) || _record_port($target);
    _require(_whole_record($source) && _whole_record($target),
        "$context whole record port copy requires declared record roots");
    _require($target->{role} ne 'input',
        "$context cannot write declared input '$target->{root}'");
    _require(!FSM::Composition::InterfacePortBuilder->declared_type_conflicts(
        $source->{type_spec}, $target->{type_spec}),
        "$context record port copy from '$source->{root}' to '$target->{root}' requires the same resolved record type");
    return 1;
}

sub _validate_reference {
    my ($value, $context) = @_;
    _keys($value, [qw(root role path_text type_spec width)], [qw(low high)], "$context value");
    _require(_identifier($value->{root}) && _role($value->{role})
        && defined($value->{path_text}) && !ref($value->{path_text}), "$context has invalid declaration facts");
    _validate_type($value->{type_spec}, $context);
    _require(_positive($value->{width}) && $value->{width} == $value->{type_spec}{width},
        "$context value width disagrees with resolved type");
    my $leaf = length($value->{path_text}) ? 1 : 0;
    _require($leaf == (exists($value->{low}) && exists($value->{high}) ? 1 : 0),
        "$context value range disagrees with path");
    _require($leaf || (!exists($value->{low}) && !exists($value->{high})),
        "$context whole value cannot have a range");
    if ($leaf) {
        _require(!_aggregate($value->{type_spec}) && _nonnegative($value->{low})
            && _nonnegative($value->{high}) && $value->{high} - $value->{low} + 1 == $value->{width},
            "$context has invalid scalar range");
    }
}

sub _validate_type {
    my ($spec, $context) = @_;
    _require(ref($spec) eq 'HASH', "$context lacks a resolved type");
    # The qualified declaration producer owns recursive layout, cycle, width,
    # member inventory and scalar-property validation. A wrapper lets the same
    # check consume existing list storage without admitting list-root ports.
    my $checked = $spec;
    if (($spec->{kind} // '') eq 'list') {
        $checked = _wrapper($spec);
    }
    my $ok = eval {
        capture_interface_port_metadata({inputs => [{name => 'value', type => 'resolved_value',
            width => $checked->{width}, type_spec => $checked}], outputs => []});
        1;
    };
    my $error = $@;
    _require($ok, "$context has invalid resolved type: $error");
    _closed_type($spec, $context);
}

sub _closed_type {
    my ($spec, $context) = @_;
    my $kind = $spec->{kind};
    my @extra = $kind eq 'record' ? qw(members member_order) : $kind eq 'list' ? ('items') : ();
    _keys($spec, [qw(kind width signed), @extra],
        _aggregate($spec) ? [] : ['state_model'], "$context resolved type");
    _require(_binary($spec->{signed}), "$context has invalid resolved signed fact");
    if (_aggregate($spec)) {
        _require($spec->{signed} == 0, "$context aggregate has a scalar signed overlay");
        my @children = $kind eq 'record'
            ? map { $spec->{members}{$_} } @{$spec->{member_order}}
            : @{$spec->{items}};
        _closed_type($_, $context) for @children;
    }
}

sub _record_port {
    my ($value) = @_;
    return 0 unless _whole_record($value);
    return ($value->{role} eq 'input' || $value->{role} eq 'output') ? 1 : 0;
}
sub _wrapper {
    my ($spec) = @_;
    return {kind => 'record', width => $spec->{width}, signed => 0,
        member_order => ['value'], members => {value => $spec}};
}
sub _whole_record {
    my ($value) = @_;
    return (ref($value) eq 'HASH' && !length($value->{path_text})
        && $value->{type_spec}{kind} eq 'record') ? 1 : 0;
}
sub _aggregate { ($_[0]{kind} eq 'record' || $_[0]{kind} eq 'list') ? 1 : 0 }
sub _identifier { (defined($_[0]) && !ref($_[0]) && $_[0] =~ /\A[A-Za-z_]\w*\z/) ? 1 : 0 }
sub _role { (defined($_[0]) && !ref($_[0]) && $_[0] =~ /\A(?:input|output|storage|local)\z/) ? 1 : 0 }
sub _text { (defined($_[0]) && !ref($_[0]) && length($_[0])) ? 1 : 0 }
sub _positive { (defined($_[0]) && !ref($_[0]) && $_[0] =~ /\A[1-9][0-9]*\z/) ? 1 : 0 }
sub _nonnegative { (defined($_[0]) && !ref($_[0]) && $_[0] =~ /\A(?:0|[1-9][0-9]*)\z/) ? 1 : 0 }
sub _binary { (defined($_[0]) && !ref($_[0]) && $_[0] =~ /\A[01]\z/) ? 1 : 0 }
sub _keys {
    my ($value, $required, $optional, $context) = @_;
    _require(ref($value) eq 'HASH', "$context must be a map");
    my %allowed = map { $_ => 1 } (@$required, @$optional);
    _require(!grep(!exists($value->{$_}), @$required), "$context lacks required facts");
    _require(!grep(!$allowed{$_}, keys %$value), "$context has unknown facts");
}
sub _require {
    confess "Invalid ISF record value: validation requires a predicate and message\n" unless @_ == 2;
    confess "Invalid ISF record value: $_[1]\n" unless $_[0];
}

1;

metadata.cause_model:
"""Independent finite validation/cause model over qualified source inputs.

This models the pinned original record-value workload, not arbitrary Perl APIs.
Primitive projection below is used only for declared physical predicates;
source graphs and raw kinds remain separately qualified by the prerequisites.
"""
import re


class Primary(ValueError):
    pass


def must(condition, message):
    if not condition:
        raise Primary(message)


def scalar(value):
    return type(value) in (str, int)


def positive(value):
    return scalar(value) and re.fullmatch(r'[1-9][0-9]*', str(value)) is not None


def binary(value):
    return scalar(value) and str(value) in ('0', '1')


def identifier(value):
    return type(value) is str and re.fullmatch(r'[A-Za-z_]\w*', value) is not None


def role(value):
    return value in ('input', 'output', 'storage', 'local')


def keys(value, required, optional, context):
    must(type(value) is dict, context + ' must be a map')
    must(set(required) <= set(value), context + ' lacks required facts')
    must(set(value) <= set(required) | set(optional), context + ' has unknown facts')


def metadata_type(spec, path='', active=None):
    active = set() if active is None else active
    must(type(spec) is dict, 'invalid resolved member type')
    must(id(spec) not in active, 'cyclic resolved type')
    active = active | {id(spec)}
    must(positive(spec.get('width')), 'invalid resolved type width')
    kind = spec.get('kind', '')
    if kind in ('bit', 'bits'):
        must(kind != 'bit' or int(spec['width']) == 1, 'bit type width must be one')
        must('signed' not in spec or binary(spec['signed']), 'invalid resolved signed property')
        must('state_model' not in spec or spec['state_model'] in ('two_state', 'four_state'), 'invalid resolved state model')
        return
    width = 0
    if kind == 'record':
        members, order = spec.get('members'), spec.get('member_order')
        must(type(members) is dict and type(order) is list and bool(order), 'record requires ordered members')
        must(len(members) == len(order), 'record member inventory disagrees')
        seen = set()
        for name in order:
            must(identifier(name) and name not in seen and name in members, 'invalid or duplicate record member')
            seen.add(name)
            metadata_type(members[name], path + '.' + name, active)
            width += int(members[name]['width'])
    elif kind == 'list':
        must(bool(path), 'list-root interface metadata remains unsupported')
        items = spec.get('items')
        must(type(items) is list and bool(items), 'list requires ordered items')
        for index, item in enumerate(items):
            metadata_type(item, path + '[' + str(index) + ']', active)
            width += int(item['width'])
    else:
        raise Primary('unsupported resolved type kind')
    must(width == int(spec['width']), 'resolved aggregate width disagrees with members')


def closed_type(spec, context):
    kind = spec['kind']
    extra = ['members', 'member_order'] if kind == 'record' else ['items'] if kind == 'list' else []
    keys(spec, ['kind', 'width', 'signed'] + extra, [] if extra else ['state_model'], context + ' resolved type')
    must(binary(spec['signed']), context + ' has invalid resolved signed fact')
    if extra:
        must(int(spec['signed']) == 0, context + ' aggregate has a scalar signed overlay')
        children = [spec['members'][name] for name in spec['member_order']] if kind == 'record' else spec['items']
        for child in children:
            closed_type(child, context)


def value_type(spec, context):
    must(type(spec) is dict, context + ' lacks a resolved type')
    checked = dict(kind='record', width=spec['width'], signed=0,
                   member_order=['value'], members={'value': spec}) if spec.get('kind') == 'list' else spec
    try:
        metadata_type(checked)
    except Primary as error:
        raise Primary(context + ' has invalid resolved type: Invalid ISF interface port metadata: ' + str(error))
    closed_type(spec, context)


def signature(value):
    if type(value) is dict:
        return tuple((key, signature(value[key])) for key in sorted(value))
    if type(value) is list:
        return tuple(signature(item) for item in value)
    return str(value) if value is not None else None


def reference_value(value, context):
    keys(value, ['root', 'role', 'path_text', 'type_spec', 'width'], ['low', 'high'], context + ' value')
    must(identifier(value['root']) and role(value['role']) and type(value['path_text']) is str,
         context + ' has invalid declaration facts')
    value_type(value['type_spec'], context)
    must(positive(value['width']) and int(value['width']) == int(value['type_spec']['width']),
         context + ' value width disagrees with resolved type')
    leaf = bool(value['path_text'])
    must(leaf == ('low' in value and 'high' in value), context + ' value range disagrees with path')
    must(leaf or ('low' not in value and 'high' not in value), context + ' whole value cannot have a range')
    if leaf:
        must(value['type_spec']['kind'] not in ('record', 'list') and int(value['low']) >= 0
             and int(value['high']) >= 0 and int(value['high']) - int(value['low']) + 1 == int(value['width']),
             context + ' has invalid scalar range')


def path_result(spec, path):
    while path:
        member = re.match(r'\.([A-Za-z_]\w*)', path)
        item = re.match(r'\[([0-9]+)(?::([0-9]+))?\]', path)
        if member:
            if spec['kind'] != 'record':
                return None, 'member_on_non_record'
            if member[1] not in spec['members']:
                return None, 'unknown_member'
            spec = spec['members'][member[1]]
            path = path[member.end():]
        elif item:
            index = int(item[1])
            if spec['kind'] == 'list' and item[2] is None:
                if index >= len(spec['items']):
                    return None, 'list_index_out_of_range'
                spec = spec['items'][index]
            elif spec['kind'] in ('bit', 'bits'):
                if index >= int(spec['width']):
                    return None, 'scalar_index_out_of_range'
                low = int(item[2]) if item[2] is not None else index
                if low > index:
                    return None, 'invalid_scalar_slice'
                spec = dict(kind='bits' if item[2] is not None else 'bit', width=index - low + 1, signed=0)
            else:
                return None, 'index_on_non_indexable'
            path = path[item.end():]
        else:
            return None, 'parse_error'
    return spec, None


def values(kind, arguments):
    must(type(arguments) is list and len(arguments) % 2 == 0, 'finite named source arguments')
    args = dict(zip(arguments[::2], arguments[1::2]))
    if kind == 'scope':
        keys(args, ['outer', 'local'], [], 'scope')
        for layer in ('outer', 'local'):
            roots = args[layer]
            must(type(roots) is dict, layer + ' roots must be a map')
            for name in sorted(roots):
                must(identifier(name), 'invalid declaration root')
                root = roots[name]; context = "root '" + name + "'"
                keys(root, ['role', 'type_spec'], [], context)
                must(role(root['role']), context + ' has invalid role')
                if root['type_spec'] is not None:
                    value_type(root['type_spec'], context)
    elif kind == 'reference':
        keys(args, ['scope', 'token', 'access', 'context'], ['allow_whole'], 'reference')
        context, token, access, scope = (args[key] for key in ('context', 'token', 'access', 'scope'))
        must(type(scope) is dict, 'reference scope must be a map')
        must(type(context) is str and bool(context), 'reference requires context')
        must(access in ('read', 'write'), context + ' has invalid access')
        must(binary(args.get('allow_whole', 0)), context + ' has invalid whole-value permission')
        match = re.match(r'([A-Za-z_]\w*)(.*)', token) if type(token) is str else None
        if match is None or match[1] not in scope:
            return
        name, path = match.groups(); root = scope[name]
        keys(root, ['role', 'type_spec'], [], context + " root '" + name + "'")
        must(role(root['role']), context + " root '" + name + "' has invalid role")
        must(access != 'write' or root['role'] != 'input', context + " cannot write declared input '" + token + "'")
        if root['type_spec'] is None:
            return
        value_type(root['type_spec'], context + " root '" + name + "'")
        spec = root['type_spec']
        if not path:
            must(int(args.get('allow_whole', 0)) or spec['kind'] not in ('record', 'list'),
                 context + " requires a scalar value; '" + token + "' is a whole " + spec['kind'])
        else:
            spec, code = path_result(spec, path)
            must(code is None, context + " has invalid declared path '" + token + "': " + str(code))
            must(spec['kind'] not in ('record', 'list'), context + " requires a scalar leaf; '" + token + "' resolves to " + spec['kind'])
    elif kind == 'copy':
        keys(args, ['source', 'target', 'context'], [], 'copy')
        context = args['context']; must(type(context) is str and bool(context), 'copy requires context')
        source, target = args['source'], args['target']
        for value in (source, target):
            if value is not None:
                reference_value(value, context)
        whole = lambda value: type(value) is dict and not value['path_text'] and value['type_spec']['kind'] == 'record'
        port = lambda value: whole(value) and value['role'] in ('input', 'output')
        if not (port(source) or port(target)):
            return
        must(whole(source) and whole(target), context + ' whole record port copy requires declared record roots')
        must(target['role'] != 'input', context + " cannot write declared input '" + target['root'] + "'")
        must(signature(source['type_spec']) == signature(target['type_spec']),
             context + " record port copy from '" + source['root'] + "' to '" + target['root'] + "' requires the same resolved record type")


def primary(kind, arguments):
    try:
        if kind in ('scope', 'reference', 'copy'):
            values(kind, arguments)
        elif kind == 'capture':
            interface = arguments[0]
            if interface is not None:
                for direction in ('inputs', 'outputs'):
                    for port in interface[direction]:
                        if 'type' in port:
                            metadata_type(port['type_spec'])
        # Other families retain separately qualified successful source/product
        # meanings. This finite workload has no rejection in those families.
    except Primary as error:
        prefix = 'Invalid ISF interface port metadata: ' if kind == 'capture' else 'Invalid ISF record value: '
        return prefix + str(error)
    return None

metadata.metadata:
package FSM::Support::ISFInterfacePortMetadata;

use strict;
use warnings;
use Carp qw(confess);
use Exporter 'import';
use Scalar::Util qw(refaddr);
use Storable qw(dclone);
use FSM::Package::AggregatePathSupport;

our @EXPORT_OK = qw(
    capture_interface_port_metadata
    snapshot_interface_port_metadata
    interface_port_metadata_contract
);

sub interface_port_metadata_contract {
    return {
        entry_keys => [qw(name direction width)],
        optional_entry_keys => [qw(type type_kind domain fields)],
        direction_values => [qw(input output)],
        type_kind_values => [qw(bit bits record)],
        field_keys => [qw(path width lsb msb signed)],
        optional_field_keys => ['state_model'],
        field_signed_values => [0, 1],
        field_state_model_values => [qw(two_state four_state)],
        shape => 'declared inputs in source order followed by declared outputs in source order; empty for a known empty interface; null when declaration metadata is unknown',
        field_layout => 'record scalar leaves in authored traversal order; port-relative member/item paths; first leaf most significant; inclusive packed ranges',
        meaning => 'declared ISF interface metadata; no inferred signals, private handoffs, source admission or hardware behavior is established by this projection',
    };
}

# The parser will supply its validated declarations. This producer is also
# tested on resolved record types before record source admission is enabled.
# It projects explicit properties rather than exporting parser/type objects.
sub capture_interface_port_metadata {
    my ($interface, $default_domain) = @_;
    return undef unless defined $interface;
    _require(ref($interface) eq 'HASH', 'expected declared interface');
    $interface = dclone($interface);
    _require(!defined($default_domain) || _identifier($default_domain), 'invalid default domain');
    my @ports;
    for my $pair (['inputs', 'input'], ['outputs', 'output']) {
        my ($key, $direction) = @$pair;
        _require(ref($interface->{$key}) eq 'ARRAY', "expected $key array");
        for my $port (@{$interface->{$key}}) {
            _require(ref($port) eq 'HASH', 'expected declared port');
            _require(_name($port->{name}), 'invalid declared port name');
            _require(_positive_integer($port->{width}), 'invalid declared port width');
            my %entry = (name => $port->{name}, direction => $direction, width => $port->{width});
            my $domain = defined($port->{domain}) ? $port->{domain} : $default_domain;
            $entry{domain} = $domain if defined $domain;
            if (exists $port->{type}) {
                $entry{type} = $port->{type};
                my $spec = $port->{type_spec};
                _require(ref($spec) eq 'HASH', "port '$port->{name}' lacks resolved type");
                my @paths;
                _collect_scalar_paths($spec, '', \@paths, {});
                _require(_positive_integer($port->{width}) && $port->{width} == $spec->{width},
                    "port '$port->{name}' type width disagrees");
                $entry{type_kind} = $spec->{kind};
                if ($spec->{kind} eq 'record') {
                    $entry{fields} = [map { _field_metadata($spec, $_) } @paths];
                } else {
                    _require($spec->{kind} eq 'bit' || $spec->{kind} eq 'bits',
                        "port '$port->{name}' unsupported root type");
                }
            } else {
                _require(!exists($port->{type_spec}), "port '$port->{name}' has type facts without an alias");
            }
            push @ports, \%entry;
        }
    }
    return snapshot_interface_port_metadata(\@ports);
}

sub _collect_scalar_paths {
    my ($spec, $path, $paths, $active) = @_;
    _require(ref($spec) eq 'HASH', 'invalid resolved member type');
    my $address = refaddr($spec);
    _require(!$active->{$address}, 'cyclic resolved type');
    local $active->{$address} = 1;
    _require(_positive_integer($spec->{width}), 'invalid resolved type width');
    my $kind = $spec->{kind} // '';
    if ($kind eq 'bit' || $kind eq 'bits') {
        _require($kind ne 'bit' || $spec->{width} == 1, 'bit type width must be one');
        _require(!exists($spec->{signed}) || _binary($spec->{signed}), 'invalid resolved signed property');
        _require(!exists($spec->{state_model}) || _state_model($spec->{state_model}), 'invalid resolved state model');
        push @$paths, $path;
        return;
    }
    my $width = 0;
    if ($kind eq 'record') {
        my ($members, $order) = @{$spec}{qw(members member_order)};
        _require(ref($members) eq 'HASH' && ref($order) eq 'ARRAY' && scalar(@$order),
            'record requires ordered members');
        _require(keys(%$members) == @$order, 'record member inventory disagrees');
        my %seen;
        for my $name (@$order) {
            _require(_identifier($name) && !$seen{$name}++ && exists($members->{$name}),
                'invalid or duplicate record member');
            _collect_scalar_paths($members->{$name}, "$path.$name", $paths, $active);
            $width += $members->{$name}{width};
        }
    } elsif ($kind eq 'list') {
        _require(length($path), 'list-root interface metadata remains unsupported');
        my $items = $spec->{items};
        _require(ref($items) eq 'ARRAY' && scalar(@$items), 'list requires ordered items');
        for my $index (0 .. $#$items) {
            _collect_scalar_paths($items->[$index], "$path\[$index\]", $paths, $active);
            $width += $items->[$index]{width};
        }
    } else {
        _require(0, 'unsupported resolved type kind');
    }
    _require($width == $spec->{width}, 'resolved aggregate width disagrees with members');
}

sub _field_metadata {
    my ($spec, $path) = @_;
    my $resolved = FSM::Package::AggregatePathSupport->resolve_packed_range(
        root_type_spec => $spec, path_text => $path,
    );
    _require($resolved->{ok}, 'declared record field has no packed range');
    my $leaf = $resolved->{type_spec};
    (my $relative_path = $path) =~ s/^\.//;
    my %field = (
        path => $relative_path, width => 0 + $resolved->{width},
        lsb => 0 + $resolved->{low}, msb => 0 + $resolved->{high},
        signed => ($leaf->{signed} // 0) ? 1 : 0,
    );
    $field{state_model} = $leaf->{state_model} if exists $leaf->{state_model};
    return \%field;
}

# Unknown provenance stays unknown. Known metadata is checked and rebuilt so
# each consumer receives a closed detached value, including nested fields.
sub snapshot_interface_port_metadata {
    my ($value) = @_;
    return undef unless defined $value;
    _require(ref($value) eq 'ARRAY', 'expected port metadata array');
    $value = dclone($value);
    my (@ports, %seen);
    my $outputs_started = 0;
    for my $port (@$value) {
        _require(ref($port) eq 'HASH', 'expected port metadata entry');
        _closed_keys($port, [qw(name direction width)], [qw(type type_kind domain fields)]);
        _require(_name($port->{name}) && !$seen{$port->{name}}++, 'invalid or duplicate port name');
        _require(defined($port->{direction}) && !ref($port->{direction})
            && scalar($port->{direction} =~ /\A(?:input|output)\z/), 'invalid direction');
        _require($port->{direction} ne 'input' || !$outputs_started, 'inputs must precede outputs');
        $outputs_started = 1 if $port->{direction} eq 'output';
        _require(_positive_integer($port->{width}), 'invalid port width');
        my %copy = (name => $port->{name}, direction => $port->{direction}, width => 0 + $port->{width});
        if (exists $port->{domain}) {
            _require(_identifier($port->{domain}), 'invalid domain');
            $copy{domain} = $port->{domain};
        }
        if (exists $port->{type}) {
            _require(defined($port->{type}) && !ref($port->{type})
                && scalar($port->{type} =~ /\A[A-Za-z_]\w*(?:\.[A-Za-z_]\w*)?\z/), 'invalid type alias');
            _require(defined($port->{type_kind}) && !ref($port->{type_kind})
                && scalar($port->{type_kind} =~ /\A(?:bit|bits|record)\z/), 'invalid resolved type kind');
            _require($port->{type_kind} ne 'bit' || $port->{width} == 1, 'bit port width must be one');
            @copy{qw(type type_kind)} = @{$port}{qw(type type_kind)};
        } else {
            _require(!exists($port->{type_kind}) && !exists($port->{fields}), 'type facts require an alias');
        }
        if (($port->{type_kind} // '') eq 'record') {
            $copy{fields} = _snapshot_fields($port->{fields}, $port->{width});
        } else {
            _require(!exists($port->{fields}), 'scalar port cannot have record fields');
        }
        push @ports, \%copy;
    }
    return \@ports;
}

sub _snapshot_fields {
    my ($fields, $width) = @_;
    _require(ref($fields) eq 'ARRAY' && scalar(@$fields), 'record requires scalar field metadata');
    my (@copy, %seen);
    my $next_high = $width - 1;
    for my $field (@$fields) {
        _require(ref($field) eq 'HASH', 'expected scalar field entry');
        _closed_keys($field, [qw(path width lsb msb signed)], ['state_model']);
        my $path = $field->{path};
        _require(defined($path) && !ref($path)
            && $path =~ /\A[A-Za-z_]\w*(?:(?:\.[A-Za-z_]\w*)|(?:\[[0-9]+\]))*\z/
            && !$seen{$path}++, 'invalid or duplicate field path');
        _require(_positive_integer($field->{width}) && _nonnegative_integer($field->{lsb})
            && _nonnegative_integer($field->{msb}) && $field->{msb} == $next_high
            && $field->{msb} - $field->{lsb} + 1 == $field->{width}, 'field ranges do not form ordered packed layout');
        _require(_binary($field->{signed}), 'invalid scalar field signed property');
        my %entry = (path => $path, map { $_ => 0 + $field->{$_} } qw(width lsb msb signed));
        if (exists $field->{state_model}) {
            _require(_state_model($field->{state_model}), 'invalid scalar field state model');
            $entry{state_model} = $field->{state_model};
        }
        push @copy, \%entry;
        $next_high = $field->{lsb} - 1;
    }
    _require($next_high == -1, 'record field layout does not cover the port');
    return \@copy;
}

sub _closed_keys {
    my ($value, $required, $optional) = @_;
    my %allowed = map { $_ => 1 } (@$required, @$optional);
    _require(!grep(!exists($value->{$_}), @$required), 'missing metadata key');
    _require(!grep(!$allowed{$_}, keys %$value), 'unknown metadata key');
}

# Predicate results must be single values in argument-list context: a failed
# regex otherwise returns an empty list and shifts the diagnostic into slot 0.
sub _name { (defined($_[0]) && !ref($_[0]) && length($_[0])) ? 1 : 0 }
sub _identifier { (defined($_[0]) && !ref($_[0]) && $_[0] =~ /\A[A-Za-z_]\w*\z/) ? 1 : 0 }
sub _positive_integer { (defined($_[0]) && !ref($_[0]) && $_[0] =~ /\A[1-9][0-9]*\z/) ? 1 : 0 }
sub _nonnegative_integer { (defined($_[0]) && !ref($_[0]) && $_[0] =~ /\A(?:0|[1-9][0-9]*)\z/) ? 1 : 0 }
sub _binary { (defined($_[0]) && !ref($_[0]) && $_[0] =~ /\A[01]\z/) ? 1 : 0 }
sub _state_model { (defined($_[0]) && !ref($_[0]) && $_[0] =~ /\A(?:two_state|four_state)\z/) ? 1 : 0 }
sub _require {
    confess "Invalid ISF interface port metadata: validation requires a predicate and message\n"
        unless @_ == 2;
    confess "Invalid ISF interface port metadata: $_[1]\n" unless $_[0];
}

1;

helper.facade:
package FSM::Adapter::ISF;

use v5.20;
use strict;
use warnings;
use Carp qw(confess);
use Scalar::Util qw(blessed);
use feature qw(signatures postderef);
no warnings 'experimental::signatures';

use FSM::Adapter::ISF::Parser;
use FSM::Debug;

# ISF Adapter — facade for .isf intent scheduling format parsing
#
# Parses .isf source files into a typed AST that the scheduler consumes.
# Uses Lispish::multi for the raw parse, then validates and classifies
# the AST structure.

sub new($class, @constructor_args) {
    _validate_constructor_receiver($class);
    my %args = _validate_constructor_args($class, @constructor_args);
    my $debug = $args{debug} // 0;

    fsm_trace_enter('Initialize ISF adapter facade', 2);

    my $parser = FSM::Adapter::ISF::Parser->new(debug => $debug);

    my $self = bless {
        parser => $parser,
        debug  => $debug,
    }, $class;

    fsm_trace_exit('ISF adapter facade initialized', 2);
    return $self;
}

sub _validate_constructor_receiver($class) {
    confess "FSM::Adapter::ISF->new must be called with the FSM::Adapter::ISF class invocant\n"
        unless defined($class) && !ref($class) && $class eq 'FSM::Adapter::ISF';
}

sub _validate_constructor_args($class, @args) {
    confess "$class->new expects an even-length option/value list\n"
        if @args % 2;

    my %options = @args;
    my %allowed = map { $_ => 1 } qw(debug);
    for my $name (sort keys %options) {
        confess "$class->new unsupported option '$name'; supported option: debug\n"
            unless $allowed{$name};
    }

    return %options;
}

sub parse_file($self, @args) {
    _validate_object_receiver($self, 'parse_file');
    my ($isf_path) = _validate_scalar_args('parse_file', 1, @args);
    _validate_parse_file_path($isf_path);
    fsm_trace_enter("ISF parse_file: $isf_path", 2);
    fsm_debug("Parsing .isf file: $isf_path", 3);
    my $result = $self->{parser}->parse_file($isf_path);
    fsm_trace_exit("ISF parse_file completed for $isf_path", 2);
    return $result;
}

sub parse_source($self, @args) {
    _validate_object_receiver($self, 'parse_source');
    my ($source_text, $source_label) = _validate_scalar_args('parse_source', 2, @args);
    fsm_trace_enter("ISF parse_source: $source_label", 2);
    my $result = $self->{parser}->parse_source($source_text, $source_label);
    fsm_trace_exit("ISF parse_source completed for $source_label", 2);
    return $result;
}

sub _validate_object_receiver($self, $method) {
    confess "FSM::Adapter::ISF->$method must be called on an FSM::Adapter::ISF object\n"
        unless blessed($self) && $self->isa('FSM::Adapter::ISF');
}

sub _validate_scalar_args($method, $expected, @args) {
    confess "FSM::Adapter::ISF->$method expects exactly $expected scalar argument(s)\n"
        unless @args == $expected;

    for my $index (0 .. $#args) {
        my $arg = $args[$index];
        confess "FSM::Adapter::ISF->$method argument " . ($index + 1) . " must be a defined scalar\n"
            if !defined($arg) || ref($arg);
    }

    return @args;
}

sub _validate_parse_file_path($isf_path) {
    confess "FSM::Adapter::ISF->parse_file argument 1 must name a readable .isf file\n"
        unless $isf_path =~ /\.isf\z/i && -f $isf_path && -r $isf_path;
}

1;

helper.observer:
use strict;
use warnings;
use lib 'perl', 't/lib';
use Test::More;
use JSON::PP;
use Storable ();
use Scalar::Util qw(refaddr blessed);
use FSM::Support::ISFInterfacePortMetadata ();

my $base = 'docs/audits/record-value-original-candidate-20261004';
my ($mode, $output) = @ARGV;
die 'candidate mode and relative output required' unless defined $mode
    && $mode =~ /\A(?:ordinary|storable|alias|controls)\z/ && defined $output
    && $output =~ m{\Adocs/audits/record-value-original-candidate-20261004/};
require './docs/audits/record-value-original-candidate-20261004/candidate.pl';
my $json = JSON::PP->new->canonical;
my (@api, @copies, @consumers, @helpers, @parses, @warnings, @copy_assertions);
my ($test_loaded, $test_error, $test_errno);
my @trials;
our $trial_provider;
our ($active_test_copy, $candidate_calls);
my $pure_copy = \&source_value_copy;
our ($active_helper, $active_api, $active_parse);
my $clone = Storable->can('dclone');
my $capture = FSM::Support::ISFInterfacePortMetadata->can('capture_interface_port_metadata');
my $snapshot = FSM::Support::ISFInterfacePortMetadata->can('snapshot_interface_port_metadata');
my $subtest = Test::More->can('subtest');
my %assertion = map {$_ => Test::More->can($_)} qw(ok like unlike is is_deeply);

# Scalar copies precede any numeric/string interpretation. Referential paths
# retain DAG/cycle topology; native objects are outside this plain fact graph.
sub graph {
    my ($value, $seen, $path) = @_;
    return $value unless ref($value);
    die 'unqualified native graph reference' if blessed($value);
    $seen ||= {}; $path //= '';
    my $address = refaddr($value);
    return ['reference', $seen->{$address}] if exists $seen->{$address};
    $seen->{$address} = $path;
    if (ref($value) eq 'HASH') {
        my %out;
        for my $key (sort keys %$value) {
            my $escaped = $key; $escaped =~ s/~/~0/g; $escaped =~ s{/}{~1}g;
            $out{$key} = graph($value->{$key}, $seen, "$path/$escaped");
        }
        return ['hash', \%out];
    }
    return ['array', [map {graph($value->[$_], $seen, "$path/$_")} 0..$#$value]]
        if ref($value) eq 'ARRAY';
    die 'unqualified native graph reference';
}

sub refs {
    my ($value, $seen) = @_;
    $seen ||= {};
    return $seen unless ref($value);
    die 'unqualified native isolation reference' if blessed($value)
        || (ref($value) ne 'HASH' && ref($value) ne 'ARRAY');
    return $seen if $seen->{refaddr($value)}++;
    refs($_, $seen) for ref($value) eq 'HASH' ? values(%$value) : @$value;
    return $seen;
}

sub call_api {
    my ($kind, $operation, $caller, @args) = @_;
    my $before = $json->encode(graph(\@args));
    local $active_api = scalar @api;
    push @api, {kind => $kind, caller => $caller, helper => $active_helper,
        parse => $active_parse, before => $json->decode($before)};
    my ($result, $error, @local_warnings);
    my $old_warning = $SIG{__WARN__};
    my $ok;
    {
        local $SIG{__WARN__} = sub {
            push @local_warnings, @_;
            if (ref($old_warning) eq 'CODE') {$old_warning->(@_)}
            elsif (!defined($old_warning) || $old_warning ne 'IGNORE') {CORE::warn(@_)}
        };
        $ok = eval {$result = $operation->(@args); 1}; $error = $@;
    }
    my $primary = (split /\n/, $error // '')[0] // '';
    @{$api[$active_api]}{qw(after accepted error primary warnings result)} =
        (graph(\@args), $ok ? 1 : 0, $error, $primary, \@local_warnings,
            $ok ? graph($result) : undef);
    die $error unless $ok;
    return $result;
}

sub copy_value {
    my ($kind, $caller, @args) = @_;
    my $before = $json->encode(graph($args[0]));
    my $original_refs = refs($args[0]);
    my ($copy, $error);
    my $assertion_start = scalar @copy_assertions;
    my $calls = 0;
    my $ok = eval {
        if ($kind eq 'test') {
            local $active_test_copy = scalar @copies;
            local $candidate_calls = 0;
            if ($mode eq 'controls') {
                for my $provider (qw(storable alias)) {
                    local $trial_provider = $provider;
                    $candidate_calls = 0;
                    my $start = scalar @copy_assertions;
                    my $before_trial = $json->encode(graph($args[0]));
                    my $result = source_copy($args[0], "original copy $active_test_copy $provider control");
                    push @trials, {copy => $active_test_copy, provider => $provider, caller => $caller,
                        before => $json->decode($before_trial), after => graph($args[0]),
                        result => graph($result), joint => graph({input => $args[0], result => $result}),
                        assertion_start => $start, assertion_end => scalar @copy_assertions,
                        candidate_calls => $candidate_calls};
                }
                $candidate_calls = 0;
            }
            $copy = source_copy($args[0], "original copy $active_test_copy");
            $calls = $candidate_calls;
        } else {
            $copy = $clone->(@args);
        }
        1;
    }; $error = $@;
    my $copy_refs = $ok ? refs($copy) : {};
    push @copies, {kind => $kind, caller => $caller, api => $active_api,
        helper => $active_helper, parse => $active_parse,
        before => $json->decode($before), after => graph($args[0]),
        accepted => $ok ? 1 : 0, error => $error, copy => $ok ? graph($copy) : undef,
        original_reference_count => scalar(keys %$original_refs),
        copy_reference_count => scalar(keys %$copy_refs),
        shared_with_original => scalar(grep {exists $original_refs->{$_}} keys %$copy_refs),
        joint_input_result => $ok ? graph({input => $args[0], result => $copy}) : undef,
        assertion_start => $assertion_start, assertion_end => scalar @copy_assertions,
        candidate_calls => $calls};
    die $error unless $ok;
    return $copy;
}

sub parse {
    my ($kind, $operation, $caller, @args) = @_;
    # The parser object is deliberately excluded; source/path args and the whole
    # returned actor are observed through the published parser interface.
    my @inputs = @args[1..$#args];
    my $before = $json->encode(graph(\@inputs));
    local $active_parse = scalar @parses;
    push @parses, {kind => $kind, caller => $caller, helper => $active_helper,
        before => $json->decode($before), api_start => scalar @api};
    my ($result, $error);
    my $ok = eval {$result = $operation->(@args); 1}; $error = $@;
    @{$parses[$active_parse]}{qw(after accepted error primary result api_end)} =
        (graph(\@inputs), $ok ? 1 : 0, $error, (split(/\n/, $error // ''))[0] // '',
            $ok ? graph($result) : undef, scalar @api);
    die $error unless $ok;
    return $result;
}

{
